#include <iostream>
#include <cmath>
#include <iomanip>
#include <limits>

using namespace std;

// Function to calculate the distance from a point (x0, y0, z0) to a plane
// defined by the equation Ax + By + Cz + D = 0
// Returns the absolute distance
double calculateDistanceToPlane(double A, double B, double C, double D, 
                                double x0, double y0, double z0) {
    // Calculate the numerator: |Ax0 + By0 + Cz0 + D|
    double numerator = abs(A * x0 + B * y0 + C * z0 + D);

    // Calculate the denominator: sqrt(A² + B² + C²)
    double denominator = sqrt(pow(A, 2) + pow(B, 2) + pow(C, 2));

    // Avoid division by zero
    if (denominator == 0.0) {
        throw invalid_argument("Coefficients A, B, C cannot all be zero");
    }

    return numerator / denominator;
}

int main() {
    setlocale(LC_ALL, "");

    double A, B, C, D, x0, y0, z0;

    // Get plane coefficients (A, B, C, D) for Ax + By + Cz + D = 0
    cout << "=== Point to Plane Distance Calculator ===" << endl;
    cout << "Enter plane coefficients (Ax + By + Cz + D = 0):" << endl;

    try {
        cout << "A coefficient: ";
        cin >> A;
        if (cin.fail() || !isfinite(A)) {
            throw invalid_argument("Invalid A coefficient");
        }

        cout << "B coefficient: ";
        cin >> B;
        if (cin.fail() || !isfinite(B)) {
            throw invalid_argument("Invalid B coefficient");
        }

        cout << "C coefficient: ";
        cin >> C;
        if (cin.fail() || !isfinite(C)) {
            throw invalid_argument("Invalid C coefficient");
        }

        cout << "D coefficient: ";
        cin >> D;
        if (cin.fail() || !isfinite(D)) {
            throw invalid_argument("Invalid D coefficient");
        }

        // Verify at least one coefficient A, B, or C is non-zero
        if (A == 0 && B == 0 && C == 0) {
            throw invalid_argument("At least one coefficient (A, B, C) must be non-zero");
        }

        // Reset error flags
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        // Get point coordinates
        cout << "\nEnter point coordinates (x0, y0, z0):" << endl;

        cout << "x coordinate: ";
        cin >> x0;
        if (cin.fail() || !isfinite(x0)) {
            throw invalid_argument("Invalid x coordinate");
        }

        cout << "y coordinate: ";
        cin >> y0;
        if (cin.fail() || !isfinite(y0)) {
            throw invalid_argument("Invalid y coordinate");
        }

        cout << "z coordinate: ";
        cin >> z0;
        if (cin.fail() || !isfinite(z0)) {
            throw invalid_argument("Invalid z coordinate");
        }

        // Reset error flags
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');

        // Calculate distance
        double distance = calculateDistanceToPlane(A, B, C, D, x0, y0, z0);

        // Output results with 2 decimal places precision
        cout << "\n=== Results ===" << endl;
        cout << "Plane Equation: " << A << "x + " << B << "y + " << C << "z + " << D << " = 0" << endl;
        cout << "Point: (" << x0 << ", " << y0 << ", " << z0 << ")" << endl;
        cout << "Distance from point to plane: " << fixed << setprecision(2) << distance << " units" << endl;

    } catch (const exception& e) {
        cout << "\nError: " << e.what() << endl;
        return 1;
    }

    return 0;
}
